import{_ as r,o as a,c as t,ai as l}from"./chunks/framework.iNbpOH0p.js";const k=JSON.parse('{"title":"HTTP与API通信","description":"","frontmatter":{},"headers":[],"relativePath":"doc/awesome-vue/HTTP与API通信.md","filePath":"doc/awesome-vue/HTTP与API通信.md"}'),i={name:"doc/awesome-vue/HTTP与API通信.md"};function o(h,e,s,n,c,u){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="http与api通信" tabindex="-1">HTTP与API通信 <a class="header-anchor" href="#http与api通信" aria-label="Permalink to “HTTP与API通信”">​</a></h1><h2 id="http-客户端" tabindex="-1">HTTP 客户端 <a class="header-anchor" href="#http-客户端" aria-label="Permalink to “HTTP 客户端”">​</a></h2><ul><li><a href="https://github.com/axios/axios" target="_blank" rel="noreferrer">Axios</a> ⭐ 108k — 基于 Promise 的 HTTP 客户端，支持浏览器和 Node.js，提供请求/响应拦截器、自动 JSON 转换、请求取消、超时控制、XSRF 防护和上传下载进度监控，是 Vue 生态中最常用的 HTTP 请求库</li><li><a href="https://github.com/visionmedia/superagent" target="_blank" rel="noreferrer">SuperAgent</a> ⭐ 16.4k — 轻量级渐进式 HTTP 客户端，兼容浏览器和 Node.js，提供优雅的链式 API、自动 JSON 解析、文件上传和 multipart 表单提交，支持插件扩展</li><li><a href="https://github.com/sindresorhus/got" target="_blank" rel="noreferrer">Got</a> ⭐ 15.6k — Node.js 环境下功能强大的 HTTP 请求库，内置分页、缓存、重试、钩子系统、流式响应和 HTTP/2 支持，适合服务端复杂 HTTP 场景</li><li><a href="https://github.com/sindresorhus/ky" target="_blank" rel="noreferrer">Ky</a> ⭐ 13.8k — 基于 Fetch API 的轻量级 HTTP 客户端，体积仅约 3KB，支持超时、自动重试、拦截器、Schema 校验和 TypeScript 类型推断，适用于浏览器和 Node.js</li><li><a href="https://github.com/pagekit/vue-resource" target="_blank" rel="noreferrer">Vue Resource</a> ⭐ 10.5k — Vue.js 早期官方 HTTP 客户端插件（已归档停维，推荐迁移至 Axios），提供拦截器、请求/响应转换和基于 Promise 的 API，曾是 Vue 1/2 时代的标配</li><li><a href="https://github.com/unjs/ofetch" target="_blank" rel="noreferrer">ofetch</a> ⭐ 5.9k — 基于原生 Fetch API 的智能封装，自动解析 JSON、智能处理错误、支持自动重试和拦截器，Nuxt 3 内置使用，适用于 Node.js、浏览器和 Worker 环境</li><li><a href="https://github.com/elbywan/wretch" target="_blank" rel="noreferrer">Wretch</a> ⭐ 5.1k — 基于 Fetch API 的超轻量封装（gzip 后约 1.8KB），提供不可变链式 API、中间件系统、错误处理辅助方法和 TypeScript 支持，兼容浏览器、Node.js、Deno 和 Bun</li><li><a href="https://github.com/ecyrbe/zodios" target="_blank" rel="noreferrer">Zodios</a> ⭐ 3.2k — 基于 Zod 和 Axios 的类型安全 API 客户端，提供端到端类型校验、请求/响应自动验证、完整的 IDE 自动补全和插件系统</li><li><a href="https://github.com/flawiddsouza/Restfox" target="_blank" rel="noreferrer">Restfox</a> ⭐ 2.7k — 基于 Vue 3 的离线优先 HTTP/WebSocket 测试客户端，支持环境变量、请求历史、插件扩展和 PWA 部署，可用作 Postman 的轻量级替代品</li><li><a href="https://github.com/imcvampire/vue-axios" target="_blank" rel="noreferrer">vue-axios</a> ⭐ 2.5k — Axios 的 Vue 插件封装，将 Axios 实例注入 Vue 应用上下文，支持 Vue 2/3，提供简洁的全局 HTTP 请求方案</li><li><a href="https://github.com/developit/unfetch" target="_blank" rel="noreferrer">Unfetch</a> ⭐ 5.7k — 超轻量级 fetch 封装（~500B），兼容浏览器和 Node.js，API 与原生 fetch 一致，Vue 项目中替代 Axios 的极简 HTTP 方案</li><li><a href="https://github.com/lquixada/cross-fetch" target="_blank" rel="noreferrer">Cross Fetch</a> ⭐ 4.5k — 跨平台 fetch 实现，统一浏览器、Node.js 和 React Native 的 HTTP 请求接口，Vue SSR 项目中保持一致请求体验</li></ul><h2 id="api-开发与管理平台" tabindex="-1">API 开发与管理平台 <a class="header-anchor" href="#api-开发与管理平台" aria-label="Permalink to “API 开发与管理平台”">​</a></h2><ul><li><a href="https://github.com/hoppscotch/hoppscotch" target="_blank" rel="noreferrer">Hoppscotch</a> ⭐ 67k — 基于 Vue 3 构建的开源 API 开发生态平台，支持 REST/GraphQL/WebSocket/MQTT/SSE，提供 Tauri 桌面客户端和 CLI 工具，是 Postman 的主流开源替代方案</li><li><a href="https://github.com/swagger-api/swagger-ui" target="_blank" rel="noreferrer">Swagger UI</a> ⭐ 30.5k — 业界标准的 OpenAPI 文档可视化工具，从 OpenAPI 规范动态生成交互式 API 文档，支持在线调试和请求测试</li><li><a href="https://github.com/Redocly/redoc" target="_blank" rel="noreferrer">Redoc</a> ⭐ 23k — 基于 OpenAPI 规范的 API 文档生成工具，提供三栏响应式布局和深度搜索功能，Vue 项目常用作文档展示方案</li><li><a href="https://github.com/scalar/scalar" target="_blank" rel="noreferrer">Scalar</a> ⭐ 21.0k — 现代化的 API 文档与交互式参考工具，支持从 OpenAPI/Swagger 规范生成美观的文档界面，提供 Vue 组件可直接嵌入项目</li><li><a href="https://github.com/swagger-api/swagger-editor" target="_blank" rel="noreferrer">Swagger Editor</a> ⭐ 8.8k — Swagger 官方 OpenAPI 可视化编辑器，支持实时 YAML/JSON 编辑与预览，帮助开发者快速设计和编写 API 规范</li></ul><h2 id="graphql-与类型安全-api" tabindex="-1">GraphQL 与类型安全 API <a class="header-anchor" href="#graphql-与类型安全-api" aria-label="Permalink to “GraphQL 与类型安全 API”">​</a></h2><ul><li><a href="https://github.com/apollographql/apollo-client" target="_blank" rel="noreferrer">Apollo Client</a> ⭐ 19.3k — 业界领先的 GraphQL 客户端，支持 React/Vue/Angular/Svelte 等多框架，提供零配置缓存、TypeScript 优先设计和声明式数据管理</li><li><a href="https://github.com/jasonkuhrt/graphql-request" target="_blank" rel="noreferrer">graphql-request</a> ⭐ 11.5k — 最小化的 GraphQL 客户端，API 简洁直观，支持浏览器和 Node.js，内置 TypeScript 类型支持</li><li><a href="https://github.com/dotansimha/graphql-code-generator" target="_blank" rel="noreferrer">graphql-code-generator</a> ⭐ 11k — 基于 GraphQL Schema 自动生成 TypeScript 类型和 Vue Composition 函数，大幅提升 Vue + GraphQL 开发体验和类型安全</li><li><a href="https://github.com/urql-graphql/urql" target="_blank" rel="noreferrer">urql</a> ⭐ 9.7k — 高度可扩展的 GraphQL 客户端，支持 Vue 集成，提供灵活的缓存策略、分页处理和订阅功能</li><li><a href="https://github.com/vuejs/apollo" target="_blank" rel="noreferrer">Vue Apollo</a> ⭐ 3.0k — Apollo GraphQL 的官方 Vue.js 集成库，支持查询、变更和订阅操作，提供智能缓存、DevTools 集成和 TypeScript 类型生成</li><li><a href="https://github.com/apollographql/graphql-tag" target="_blank" rel="noreferrer">graphql-tag</a> ⭐ 2.3k — Apollo 出品的 GraphQL 查询模板字面量解析工具，支持 .gql/.graphql 文件直接在 Vue SFC 中内联编写查询语句</li><li><a href="https://github.com/logaretm/villus" target="_blank" rel="noreferrer">villus</a> ⭐ 850 — 专为 Vue 3 设计的小巧 GraphQL 客户端，体积小于 4KB，支持 Composition API、Suspense 和 TypeScript 类型推断</li></ul><h2 id="数据获取与缓存管理" tabindex="-1">数据获取与缓存管理 <a class="header-anchor" href="#数据获取与缓存管理" aria-label="Permalink to “数据获取与缓存管理”">​</a></h2><ul><li><a href="https://github.com/alovajs/alova" target="_blank" rel="noreferrer">Alova</a> ⭐ 4.7k — 新一代轻量级请求策略库，API 极简，内置请求缓存、请求共享、重试机制、进度追踪和工作流编排，支持 Vue/React/Svelte/小程序等多平台</li><li><a href="https://github.com/unplugin/unplugin-auto-import" target="_blank" rel="noreferrer">unplugin-auto-import</a> ⭐ 3.8k — 通用构建工具插件，可按需自动导入 VueUse、Alova 等库的组合式函数，减少手动 import 样板代码</li><li><a href="https://github.com/Kong/swrv" target="_blank" rel="noreferrer">swrv</a> ⭐ 3.0k — Kong 开源的 stale-while-revalidate 缓存策略 Vue 3 实现，支持数据缓存、自动重新验证、乐观更新和错误重试</li><li><a href="https://github.com/robsontenorio/vue-api-query" target="_blank" rel="noreferrer">Vue API Query</a> ⭐ 1.8k — 声明式 REST API 查询构建器，为 Vue 项目提供 Eloquent 风格的 API 查询语法，简化 RESTful 接口调用和数据管理</li><li><a href="https://github.com/Attojs/vue-request" target="_blank" rel="noreferrer">Vue Request</a> ⭐ 1.4k — 受 SWR 启发的 Vue 数据请求库，支持缓存、重试、防抖节流、轮询和分页等高级特性，兼容 Vue 2/3</li></ul><h2 id="baas-后端即服务" tabindex="-1">BaaS / 后端即服务 <a class="header-anchor" href="#baas-后端即服务" aria-label="Permalink to “BaaS / 后端即服务”">​</a></h2><ul><li><a href="https://github.com/appwrite/appwrite" target="_blank" rel="noreferrer">Appwrite</a> ⭐ 56k — 开源 Firebase 替代方案，提供数据库、认证、存储、云函数和实时功能等完整后端服务，支持自部署和多平台 SDK</li><li><a href="https://github.com/directus/directus" target="_blank" rel="noreferrer">Directus</a> ⭐ 34.0k — 开源 Headless CMS 和数据平台，可将任何 SQL 数据库即时转换为 REST/GraphQL API，提供完整的 Vue 集成方案</li><li><a href="https://github.com/firebase/firebase-js-sdk" target="_blank" rel="noreferrer">Firebase JS SDK</a> ⭐ 4.8k — Firebase 官方 JavaScript SDK，提供认证、数据库、存储、云函数等完整的 Firebase 服务端能力，是 Vuefire 的底层依赖</li><li><a href="https://github.com/supabase/supabase-js" target="_blank" rel="noreferrer">Supabase JS</a> ⭐ 4.2k — Supabase 官方 JavaScript SDK，提供数据库查询、实时订阅、文件存储和身份验证等功能，是 Firebase 的开源替代方案</li><li><a href="https://github.com/vuejs/vuefire" target="_blank" rel="noreferrer">Vuefire</a> ⭐ 3.1k — Vue.js 官方 Firebase 绑定库，以声明式方式将 Firestore 和 Realtime Database 数据绑定到 Vue 组件，自动处理数据同步和状态更新</li><li><a href="https://github.com/pocketbase/js-sdk" target="_blank" rel="noreferrer">PocketBase JS SDK</a> ⭐ 2.5k — 轻量级开源 BaaS PocketBase 的官方 JS SDK，支持认证管理、数据库操作和文件存储，与 Vue 生态配合良好</li></ul><h2 id="实时通信-websocket-sse" tabindex="-1">实时通信 (WebSocket/SSE) <a class="header-anchor" href="#实时通信-websocket-sse" aria-label="Permalink to “实时通信 (WebSocket/SSE)”">​</a></h2><ul><li><a href="https://github.com/socketio/socket.io-client" target="_blank" rel="noreferrer">Socket.IO Client</a> ⭐ 15.2k — Socket.IO 官方 JavaScript 客户端，提供实时双向事件驱动通信、自动重连、命名空间和房间功能</li><li><a href="https://github.com/sockjs/sockjs-client" target="_blank" rel="noreferrer">SockJS Client</a> ⭐ 8.6k — SockJS 浏览器客户端，在浏览器和服务器之间建立实时双向通道，不支持 WebSocket 时自动降级到其他传输方式</li><li><a href="https://github.com/mqttjs/MQTT.js" target="_blank" rel="noreferrer">MQTT.js</a> ⭐ 7.1k — MQTT 协议 JavaScript 客户端，适用于物联网设备通信和消息队列场景，支持 QoS 等级、持久化会话和 WebSocket/WSS 传输</li><li><a href="https://github.com/Azure/fetch-event-source" target="_blank" rel="noreferrer">fetch-event-source</a> ⭐ 3.3k — 微软开源的 SSE 客户端库，基于 Fetch API 实现，支持自动重连、流式响应处理和身份验证，适用于 AI 对话流式输出等场景</li><li><a href="https://github.com/unjs/crossws" target="_blank" rel="noreferrer">crossws</a> ⭐ 1.6k — 跨平台 WebSocket 库，支持 Node.js、Deno、Bun 和浏览器，提供统一的 WebSocket API 和适配器模式</li><li><a href="https://github.com/MetinSeylan/Vue-Socket.io" target="_blank" rel="noreferrer">Vue Socket.io</a> ⭐ 1.5k — Socket.io 的 Vue 集成库，提供声明式事件绑定和全局 Socket 实例管理，支持 Vue 2/3</li><li><a href="https://github.com/Yaffle/EventSource" target="_blank" rel="noreferrer">EventSource Polyfill</a> ⭐ 1.5k — SSE (Server-Sent Events) Polyfill 实现，为不支持 EventSource API 的浏览器提供兼容层</li><li><a href="https://github.com/icebob/vue-websocket" target="_blank" rel="noreferrer">vue-websocket</a> ⭐ 1.2k — Vue 原生 WebSocket 插件，通过 $socket API 和声明式事件订阅简化实时通信开发，支持自动重连和心跳检测</li><li><a href="https://github.com/nathantsoi/vue-native-websocket" target="_blank" rel="noreferrer">vue-native-websocket</a> ⭐ 1.0k — 原生 WebSocket 的 Vue 实现，支持 Vue 2/3，提供声明式事件绑定、自动重连、心跳检测、Vuex 集成和二进制数据传输</li><li><a href="https://github.com/stomp-js/stompjs" target="_blank" rel="noreferrer">STOMP.js</a> ⭐ 880 — STOMP 协议的 JavaScript 客户端，常与 WebSocket/SockJS 配合使用，实现面向消息的发布/订阅通信模式</li></ul><h2 id="文件上传" tabindex="-1">文件上传 <a class="header-anchor" href="#文件上传" aria-label="Permalink to “文件上传”">​</a></h2><ul><li><a href="https://github.com/rowanwins/vue-dropzone" target="_blank" rel="noreferrer">vue-dropzone</a> ⭐ 2k — Dropzone.js 的 Vue 封装，提供优雅的拖拽上传界面和文件预览功能，支持多文件上传和队列管理</li><li><a href="https://github.com/simple-uploader/vue-uploader" target="_blank" rel="noreferrer">vue-simple-uploader</a> ⭐ 1.5k — 基于 simple-uploader.js 的 Vue 上传组件，支持断点续传、分片上传、文件夹上传、队列管理和文件校验</li></ul><h2 id="mock-数据与测试" tabindex="-1">Mock 数据与测试 <a class="header-anchor" href="#mock-数据与测试" aria-label="Permalink to “Mock 数据与测试”">​</a></h2><ul><li><a href="https://github.com/typicode/json-server" target="_blank" rel="noreferrer">json-server</a> ⭐ 75.3k — 零代码 30 秒创建完整 REST API 的 Mock 工具，仅需一个 JSON 文件即可模拟增删改查、分页、排序和过滤等完整 API 功能</li><li><a href="https://github.com/mswjs/msw" target="_blank" rel="noreferrer">msw</a> ⭐ 20.5k — Mock Service Worker，通过 Service Worker 拦截网络层请求实现无侵入式 API Mock，同时支持浏览器和 Node.js 测试环境</li><li><a href="https://github.com/faker-js/faker" target="_blank" rel="noreferrer">Faker.js</a> ⭐ 12k — 大规模生成模拟数据的工具库，支持中文等多种语言，可与 json-server 配合在 Vue 项目中快速构建逼真的 Mock 数据集</li><li><a href="https://github.com/nock/nock" target="_blank" rel="noreferrer">Nock</a> ⭐ 12k — Node.js HTTP 拦截与 Mock 库，适合 Vue SSR（Nuxt）或 Vitest 服务端测试场景，支持条件匹配和请求断言</li><li><a href="https://github.com/miragejs/miragejs" target="_blank" rel="noreferrer">Mirage JS</a> ⭐ 5.3k — 客户端 API Mock 框架，可在浏览器端模拟完整 API 服务器，让 Vue 前端无需后端即可独立开发和测试</li><li><a href="https://github.com/ctimmerm/axios-mock-adapter" target="_blank" rel="noreferrer">Axios Mock Adapter</a> ⭐ 2.6k — Axios 请求模拟适配器，用于单元测试中拦截 Axios 请求并返回 Mock 数据，无需修改业务代码即可完成前后端分离测试</li><li><a href="https://github.com/IanVS/vitest-fetch-mock" target="_blank" rel="noreferrer">vitest-fetch-mock</a> ⭐ 520 — Vitest 专用的 Fetch API Mock 工具，兼容 jest-fetch-mock API，支持条件 Mock 和请求断言</li></ul><h2 id="本地数据存储" tabindex="-1">本地数据存储 <a class="header-anchor" href="#本地数据存储" aria-label="Permalink to “本地数据存储”">​</a></h2><ul><li><a href="https://github.com/pouchdb/pouchdb" target="_blank" rel="noreferrer">PouchDB</a> ⭐ 16.8k — 支持与 CouchDB 同步的浏览器端数据库，适用于 Vue 离线优先应用，提供强大的数据同步和冲突解决能力</li><li><a href="https://github.com/jakearchibald/idb" target="_blank" rel="noreferrer">idb</a> ⭐ 6.5k — 微型 IndexedDB Promise 封装，TypeScript 原生支持，API 简洁，是 Vue 项目轻量本地存储的首选库</li><li><a href="https://github.com/mrichar1/jsonapi-vuex" target="_blank" rel="noreferrer">jsonapi-vuex</a> ⭐ 800 — JSON:API 规范的 Vuex 集成库，自动将 JSON:API 响应转换为 Vuex Store 状态，支持关系数据加载和缓存</li></ul><h2 id="第三方服务与类型安全集成" tabindex="-1">第三方服务与类型安全集成 <a class="header-anchor" href="#第三方服务与类型安全集成" aria-label="Permalink to “第三方服务与类型安全集成”">​</a></h2><ul><li><a href="https://github.com/trpc/trpc" target="_blank" rel="noreferrer">tRPC</a> ⭐ 40.2k — 端到端类型安全的 RPC 框架，无需 Schema 或代码生成即可实现全自动类型推断和 IDE 补全，通过社区适配器可与 Vue 3 集成使用</li><li><a href="https://github.com/strapi/strapi-sdk-javascript" target="_blank" rel="noreferrer">strapi-sdk-javascript</a> ⭐ 1.2k — Strapi 官方 JavaScript SDK，提供完整的 REST/GraphQL API 客户端，方便 Vue 项目对接 Strapi 无头 CMS</li><li><a href="https://github.com/vue-stripe/vue-stripe" target="_blank" rel="noreferrer">@vue-stripe/vue-stripe</a> ⭐ 1.1k — Stripe 官方 Vue 3 集成库，提供 Checkout 和 Elements 组件，支持 40+ 支付方式和完整 TypeScript 类型</li><li><a href="https://github.com/hey-api/openapi-ts" target="_blank" rel="noreferrer">@hey-api/openapi-ts</a> ⭐ 3.2k — 现代化的 OpenAPI TypeScript 代码生成器，从 OpenAPI 规范自动生成类型安全的 HTTP 客户端代码，Vue 项目类型安全 API 调用首选</li><li><a href="https://github.com/orval-labs/orval" target="_blank" rel="noreferrer">Orval</a> ⭐ 5.2k — 从 OpenAPI/Swagger 规范自动生成 Vue/React TypeScript HTTP 客户端，集成 TanStack Query/Pinia，支持 MSW mock 和 Zod 验证</li></ul><h2 id="api网关与代理" tabindex="-1">API网关与代理 <a class="header-anchor" href="#api网关与代理" aria-label="Permalink to “API网关与代理”">​</a></h2><ul><li><a href="https://github.com/Kong/kong" target="_blank" rel="noreferrer">Kong</a> ⭐ 41.7k — 开源 API 网关，提供认证、限流、日志和监控插件，Vue 全栈项目中对前端 API 请求的统一入口管理和安全防护</li><li><a href="https://github.com/traefik/traefik" target="_blank" rel="noreferrer">Traefik</a> ⭐ 55.2k — 云原生反向代理和负载均衡器，自动发现服务和 HTTPS 证书管理，Vue Docker 部署时的 API 路由和代理方案</li><li><a href="https://github.com/NginxProxyManager/nginx-proxy-manager" target="_blank" rel="noreferrer">Nginx Proxy Manager</a> ⭐ 25.5k — Nginx 的 Web 管理界面，支持 SSL 自动续期和反向代理配置，Vue 项目自托管部署时的 API 代理管理利器</li><li><a href="https://github.com/vitejs/vite" target="_blank" rel="noreferrer">Vite Proxy</a> ⭐ 73.6k — Vite 内置开发代理功能，通过 vite.config.ts 配置代理规则，Vue 开发环境中轻松解决跨域 API 调用问题</li></ul><h2 id="请求监控与日志" tabindex="-1">请求监控与日志 <a class="header-anchor" href="#请求监控与日志" aria-label="Permalink to “请求监控与日志”">​</a></h2><ul><li><a href="https://github.com/getsentry/sentry-javascript" target="_blank" rel="noreferrer">Sentry Vue</a> ⭐ 8.4k — Sentry 前端错误监控 SDK，自动捕获 Vue 组件的 HTTP 请求错误、Promise 异常和性能瓶颈，提供完整的错误追踪和回放</li><li><a href="https://github.com/open-telemetry/opentelemetry-js" target="_blank" rel="noreferrer">OpenTelemetry JS</a> ⭐ 3.1k — OpenTelemetry JavaScript 实现，为 Vue 应用的 HTTP 请求添加分布式追踪，可视化微服务间的 API 调用链路</li></ul><h2 id="api性能测试" tabindex="-1">API性能测试 <a class="header-anchor" href="#api性能测试" aria-label="Permalink to “API性能测试”">​</a></h2><ul><li><a href="https://github.com/grafana/k6" target="_blank" rel="noreferrer">K6</a> ⭐ 28.3k — Grafana 开源的性能测试工具，用 JavaScript 编写测试脚本，对 Vue 后端 API 进行负载测试和压力测试</li><li><a href="https://github.com/artilleryio/artillery" target="_blank" rel="noreferrer">Artillery</a> ⭐ 8.9k — 云原生的负载测试工具，通过 YAML 配置发起 HTTP/WebSocket 并发测试，Vue 全栈应用的 API 性能基准测试方案</li><li><a href="https://github.com/postmanlabs/newman" target="_blank" rel="noreferrer">Postman CLI</a> ⭐ 7.1k — Postman 集合命令行运行器，CI/CD 中自动执行 Vue 项目的 API 测试集合并生成报告，实现接口测试自动化</li></ul>',27)])])}const b=r(i,[["render",o]]);export{k as __pageData,b as default};
